/* ================= Risk Workbench: risk editor, register configuration and sample risks ================= */
const RET=[['det','Details'],['ass','Assessment'],['qt','Quantitative'],['resp','Response'],['links','Links'],['hist','History']];
const rkClone=o=>JSON.parse(JSON.stringify(o));
function rkOpen(r,tab,isNew){ const b=rkBlank(rkScopeOf(r)), x=rkClone(r); x.d=Object.assign(b.d,x.d||{}); ['q','qt','resp','ifc'].forEach(k=>x.d[k]=Object.assign(rkClone(b.d[k]),x.d[k]||{}));
  RQ.forEach(k=>{ x.d.q[k]=Object.assign({p:0,i:{}},x.d.q[k]||{}); }); x.d.qt.cost=Object.assign({min:'',ml:'',max:''},x.d.qt.cost||{}); x.d.qt.time=Object.assign({min:'',ml:'',max:''},x.d.qt.time||{});
  x.d.qt.post=Object.assign({p:'',cost:{min:'',ml:'',max:''},time:{min:'',ml:'',max:''}},x.d.qt.post||{}); x.d.actions=(x.d.actions||[]).map(a=>Object.assign({id:'a'+Math.random().toString(36).slice(2,8),t:'',owner:'',due:null,status:'todo',cost:''},a));
  RK.ed={r:x,orig:JSON.stringify(x),isNew:!!isNew||!r.id}; RK.edTab=tab||'det'; rkEdRender(true); }
function rkEdClose(force){ const sh=document.getElementById('rkSheet'); if(!sh) return; RK.ed=null; sh.classList.remove('in'); const sc=document.getElementById('rkScrim'); if(sc) sc.remove(); setTimeout(()=>{ if(!RK.ed) sh.remove(); },200); }
const rkDirty=()=>RK.ed&&JSON.stringify(RK.ed.r)!==RK.ed.orig;
function rkEdRender(first){
  let sh=document.getElementById('rkSheet');
  if(!sh){ const scr=document.createElement('div'); scr.className='rk-scrim'; scr.id='rkScrim'; document.body.appendChild(scr); scr.onclick=()=>rkEdAsk();
    sh=document.createElement('aside'); sh.className='rk-sheet'; sh.id='rkSheet'; sh.setAttribute('role','dialog'); sh.setAttribute('aria-modal','true'); sh.setAttribute('aria-labelledby','rkShT'); document.body.appendChild(sh);
    sh.addEventListener('click',rkEdClick); sh.addEventListener('change',rkEdChange); sh.addEventListener('input',rkEdInput); sh.addEventListener('keydown',e=>{ if(e.key==='Escape'){ e.stopPropagation(); rkEdAsk(); } });
    requestAnimationFrame(()=>sh.classList.add('in')); }
  const E=RK.ed, r=E.r, ro=!rkCanEdit(), sc=rkScopeOf(r), body=sh.querySelector('.rk-sh-b'), top=body?body.scrollTop:0, act=document.activeElement, ak=act&&act.dataset&&act.dataset.e, ai=act&&act.dataset&&act.dataset.ai, apos=act&&act.selectionStart;
  const cs=rkCurScore(r);
  sh.innerHTML=`<div class="rk-sh-h"><div class="rk-sh-t"><div class="rk-sh-m"><span class="rk-lv l${rkRank(r.level)}">${RLV_L[r.level]}</span><span class="rk-ref">${esc(r.ref||'New risk')}</span>${rkChip(cs,{t:'Current'})}${r.d.type==='opp'?'<span class="rk-opp">Opportunity</span>':''}</div>
      <h2 id="rkShT">${esc(r.title||'New risk')}</h2><span class="muted">${esc(rkScopeName(sc))}${ro?' · view only':''}</span></div><button class="fx" data-rke="close" aria-label="Close">×</button></div>
    <div class="ptabs rk-sh-tabs" role="tablist">${RET.map(([k,l])=>`<button role="tab" aria-selected="${RK.edTab===k}" data-rket="${k}">${l}${k==='resp'&&rkActs(r).length?` <em>${rkActs(r).length}</em>`:''}${k==='links'&&(rkKids(r).length||r.parentId||rkIsIfc(r))?` <em>${(r.parentId?1:0)+rkKids(r).length+(rkIsIfc(r)?1:0)}</em>`:''}</button>`).join('')}</div>
    <div class="rk-sh-b"><fieldset ${ro?'disabled':''}>${({det:rkEdDet,ass:rkEdAss,qt:rkEdQt,resp:rkEdResp,links:rkEdLinks,hist:rkEdHist})[RK.edTab](r)}</fieldset></div>
    <div class="rk-sh-f">${ro?'':`<button class="btn primary" data-rke="save">${E.isNew?'Add risk':'Save'}</button>`}<button class="btn" data-rke="close">${ro?'Close':'Cancel'}</button>${!ro&&!E.isNew?'<button class="btn ghost" data-rke="reviewed" title="Record a review today and set the next review date">Mark reviewed</button>':''}<span class="sp"></span>${!E.isNew&&rkCanDel(r)?'<button class="link danger" data-rke="del">Delete risk</button>':''}</div>`;
  const nb=sh.querySelector('.rk-sh-b'); if(!first) nb.scrollTop=top;
  if(ak||ai){ const n=sh.querySelector(ak?`[data-e="${CSS.escape(ak)}"]`:`[data-ai="${CSS.escape(ai)}"]`); if(n){ n.focus(); try{ if(apos!=null) n.setSelectionRange(apos,apos); }catch(_){} } }
  else if(first){ const t=sh.querySelector('[data-e="title"]'); if(t&&E.isNew) t.focus(); else sh.querySelector('.fx').focus(); }
}
function rkEdAsk(){ if(!rkDirty()){ rkEdClose(); return; } const b=document.querySelector('#rkSheet [data-rke="close"]:not(.fx)'); if(b&&confirmIn(b,'Discard changes?')) rkEdClose(); else if(!b) rkEdClose(); }
/* field helpers */
const rkGet=(o,p)=>p.split('.').reduce((x,k)=>x==null?x:x[k],o);
function rkSet(o,p,v){ const ks=p.split('.'); let x=o; ks.slice(0,-1).forEach(k=>{ if(x[k]==null||typeof x[k]!=='object') x[k]={}; x=x[k]; }); x[ks[ks.length-1]]=v; }
const rkIn_=(p,v,o)=>{ o=o||{}; return `<label class="pfl ${o.cls||''}"><span>${o.l}</span>${o.ta?`<textarea data-e="${p}" rows="${o.rows||3}" placeholder="${esc(o.ph||'')}">${esc(v??'')}</textarea>`:`<input data-e="${p}" ${o.t?`type="${o.t}" data-t="${o.t}"`:''} value="${esc(o.t==='date'?(v?xD(v):''):v??'')}" placeholder="${esc(o.ph||'')}" ${o.list?`list="${o.list}"`:''} ${o.req?'required':''} ${o.step?`step="${o.step}"`:''} ${o.min!=null?`min="${o.min}"`:''}>`}${o.hint?`<small class="muted">${o.hint}</small>`:''}</label>`; };
const rkSel_=(p,v,opts,o)=>{ o=o||{}; return `<label class="pfl ${o.cls||''}"><span>${o.l}</span><select data-e="${p}" ${o.t?`data-t="${o.t}"`:''}>${opts.map(([k,l])=>`<option value="${esc(k)}"${String(v??'')===String(k)?' selected':''}>${esc(l)}</option>`).join('')}</select>${o.hint?`<small class="muted">${o.hint}</small>`:''}</label>`; };
function rkRegOpts(){ const o=[['portfolio:','Portfolio register']]; (PER.programmes||[]).forEach(g=>{ o.push(['programme:'+g.id,'Programme · '+g.name]); PER.projects.filter(p=>p.programmeId===g.id).forEach(p=>o.push(['project:'+p.id,'   Project · '+p.name])); });
  PER.projects.filter(p=>!p.programmeId||!PER.programmes.some(g=>g.id===p.programmeId)).forEach(p=>o.push(['project:'+p.id,'Project · '+p.name])); return o; }
function rkEdDet(r){ const c=rkCfg(), d=r.d, owners=[...new Set(RK.risks.flatMap(x=>[x.d.owner,(x.d.resp||{}).owner,...rkActs(x).map(a=>a.owner)]).filter(Boolean))].sort();
  const cats=[['','Choose…']].concat([...new Set(c.cats.concat(d.cat?[d.cat]:[]))].map(x=>[x,x]));
  const fv=f=>(d.f||{})[f.id];
  return `<datalist id="rkOwners">${owners.map(o=>`<option value="${esc(o)}">`).join('')}</datalist>
    ${rkIn_('title',r.title,{l:'Risk title',req:1,ph:'Short name, e.g. Late possession for depot track connection'})}
    <div class="rk-g4">${rkSel_('d.type',d.type,[['threat','Threat'],['opp','Opportunity']],{l:'Type'})}${rkSel_('status',r.status,Object.entries(RST),{l:'Status'})}${rkSel_('d.cat',d.cat,cats,{l:'Category'})}${rkIn_('d.owner',d.owner,{l:'Risk owner',list:'rkOwners',ph:'Name or role'})}</div>
    ${rkSel_('_reg',r.level+':'+(r.level==='programme'?r.programmeId:r.level==='project'?r.projectId:''),rkRegOpts(),{l:'Register',hint:'Which register owns this risk. Move it up or down as it is escalated or delegated.'})}
    <div class="rk-cee"><div class="rk-g3">${rkIn_('d.cause',d.cause,{l:'Cause',ta:1,ph:'Because of…'})}${rkIn_('d.event',d.event,{l:d.type==='opp'?'Opportunity':'Risk event',ta:1,ph:'…this may happen…'})}${rkIn_('d.effect',d.effect,{l:'Effect',ta:1,ph:'…which would lead to…'})}</div>
      ${d.cause||d.event||d.effect?`<p class="rk-stmt">Because of <b>${esc(d.cause||'…')}</b>, ${esc(d.event||'…')}, leading to <b>${esc(d.effect||'…')}</b>.</p>`:''}</div>
    ${rkIn_('d.desc',d.desc,{l:'Notes',ta:1,rows:2})}
    <div class="rk-g3">${rkIn_('d.raised',d.raised,{l:'Raised',t:'date'})}${rkIn_('d.prox',d.prox,{l:'Proximity',t:'date',hint:'When it could happen'})}${rkIn_('d.review',d.review,{l:'Next review',t:'date',hint:`Review cycle ${c.review} days`})}</div>
    ${c.fields.length?`<div class="rk-g3">${c.fields.map(f=>f.type==='choice'?rkSel_('d.f.'+f.id,fv(f),[['','—']].concat((f.opts||[]).map(o=>[o,o])),{l:f.l}):rkIn_('d.f.'+f.id,fv(f),{l:f.l,t:f.type==='number'?'number':f.type==='date'?'date':''})).join('')}</div>`:''}`; }
function rkImpOpts(dim){ const c=rkCfg(), L=c.ilab; const o=[[0,'—']];
  for(let i=1;i<=5;i++){ let d=''; if(dim.kind==='cost'||dim.kind==='time'){ const b=dim.b||[], f=dim.kind==='cost'?rkMoney:(v=>v+' d'); d=i===1?`≤ ${f(b[0])}`:i===5?`> ${f(b[3])}`:`${f(b[i-2])}–${f(b[i-1])}`; } else d=(dim.d||[])[i-1]||''; o.push([i,`${i} ${L[i-1]}${d?' · '+d:''}`]); }
  return o; }
function rkEdAss(r){ const c=rkCfg(), q=r.d.q, prev=[0].concat(c.prob.map(x=>x.max));
  const po=[[0,'—']].concat(c.prob.map((p,i)=>[i+1,`${i+1} ${p.l} · ${prev[i]}–${p.max}%`]));
  const mark={}; RQ.forEach(k=>{ const p=rkPos(r,k); if(p){ const key=p.p+'-'+p.i; mark[key]=(mark[key]||'')+`<b class="rk-mk ${k}">${RQ_L[k][0]}</b>`; } });
  const rows=`<tr><th>Probability</th>${RQ.map(k=>`<td><select data-e="d.q.${k}.p" data-t="number" aria-label="${RQ_L[k]} probability">${po.map(([v,l])=>`<option value="${v}"${+q[k].p===v?' selected':''}>${esc(l)}</option>`).join('')}</select></td>`).join('')}</tr>`+
    c.dims.map(dm=>`<tr><th>${esc(dm.l)} impact</th>${RQ.map(k=>`<td><select data-e="d.q.${k}.i.${dm.id}" data-t="number" aria-label="${RQ_L[k]} ${esc(dm.l)} impact">${rkImpOpts(dm).map(([v,l])=>`<option value="${v}"${+((q[k].i||{})[dm.id]||0)===v?' selected':''}>${esc(l)}</option>`).join('')}</select></td>`).join('')}</tr>`).join('')+
    `<tr class="rk-sc"><th>Score</th>${RQ.map(k=>`<td>${rkChip(rkQS(r,k))}</td>`).join('')}</tr>`;
  const qt=rkQt(r), sug=qt.p||qt.cost!=null||qt.time!=null;
  return `<p class="muted">Score each stage on the ${c.prob.length}×5 matrix. The score is probability × the highest impact; the rating bands are set by your admin.</p>
    <div class="rk-ass"><div class="ptw rk-assw"><table class="ptab rk-asst"><thead><tr><th></th>${RQ.map(k=>`<th title="${esc(RQ_S[k])}">${RQ_L[k]}<div class="muted rk-ths">${esc(RQ_S[k])}</div></th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>
    <div class="rk-assm">${rkHeat([],'cur',{sm:1,mark})}<div class="rk-mkl"><span><b class="rk-mk pre">I</b> Inherent</span><span><b class="rk-mk cur">C</b> Current</span><span><b class="rk-mk tgt">T</b> Target</span></div></div></div>
    <div class="adm-acts">${sug?'<button type="button" class="btn sm" data-rke="suggest" title="Set the current probability and cost and schedule impacts from the three-point estimate">Suggest current from estimate</button>':''}<button type="button" class="btn sm ghost" data-rke="copyq">Copy inherent to current</button></div>`; }
function rkEdQt(r){ const q=r.d.qt, n=rkKids(r).filter(rkLive).length, c=rkCfg(), cur=c.cur||'$';
  const tri=(p,l,u)=>`<div class="rk-tri"><span class="rk-tril">${l}</span>${['min','ml','max'].map(k=>`<label class="pfl"><span>${({min:'Minimum',ml:'Most likely',max:'Maximum'})[k]}${u?' ('+u+')':''}</span><input data-e="${p}.${k}" type="number" data-t="number" step="any" value="${esc(rkGet(r,p+'.'+k)??'')}"></label>`).join('')}</div>`;
  const ev=(post)=>`<div id="rkEv${post?1:0}">${rkEvHtml(r,post)}</div>`;
  return `${n?`<label class="tg rk-roll"><input type="checkbox" data-e="d.qt.fromKids" data-t="bool" ${q.fromKids?'checked':''}> Roll up exposure from its ${n} live child risk${n===1?'':'s'} (${rkMoney(rkKids(r).filter(rkLive).reduce((s,k)=>s+rkEV(k,false,'cost'),0))}, ${rkDays(rkKids(r).filter(rkLive).reduce((s,k)=>s+rkEV(k,false,'time'),0))})</label>`:''}
    ${q.fromKids&&n?'<p class="muted">This parent takes its exposure from its children, so totals count each estimate once. Untick to give it an estimate of its own.</p>':`
    <div class="rk-g3">${rkIn_('d.qt.p',q.p,{l:'Probability of occurring (%)',t:'number',min:0,step:'any'})}${rkSel_('d.qt.dist',q.dist||'tri',Object.entries(RDIST),{l:'Distribution',hint:'Used by Monte Carlo'})}${rkIn_('d.qt.acts',q.acts,{l:'Schedule activities affected',ph:'e.g. DP150, DP160',hint:'Activity IDs, to place the delay in the schedule later'})}</div>
    <h4 class="rk-h4">Current estimate (if it happens)</h4>${tri('d.qt.cost','Cost',cur)}${tri('d.qt.time','Schedule','days')}${ev(false)}
    <h4 class="rk-h4">After planned responses <span class="muted">optional</span></h4>
    <div class="rk-g3">${rkIn_('d.qt.post.p',q.post.p,{l:'Probability (%)',t:'number',min:0,step:'any',hint:'Leave blank if responses don’t change the estimate'})}</div>${tri('d.qt.post.cost','Cost',cur)}${tri('d.qt.post.time','Schedule','days')}${ev(true)}`}
    <p class="pn rk-mc">Monte Carlo is coming next: it will sample these three-point estimates, using each risk’s probability and distribution, to give P50 and P80 cost and finish dates.</p>`; }
function rkEvHtml(r,post){ const x=rkQt(r,post); return `<div class="rk-evs"><div><span class="sl">Cost exposure</span><b>${rkMoney(x.cost==null?null:x.p/100*x.cost)}</b><span class="muted">${x.p||0}% × mean ${rkMoney(x.cost)}</span></div><div><span class="sl">Schedule exposure</span><b>${rkDays(x.time==null?null:x.p/100*x.time)}</b><span class="muted">${x.p||0}% × mean ${rkDays(x.time)}</span></div></div>`; }
function rkEdRendered(){ const r=RK.ed&&RK.ed.r; if(!r) return; [0,1].forEach(i=>{ const el=document.getElementById('rkEv'+i); if(el) el.innerHTML=rkEvHtml(r,!!i); }); }
function rkEdResp(r){ const p=r.d.resp, S=RSTRAT[r.d.type==='opp'?'opp':'threat'];
  const hint={avoid:'Change the plan so the risk can’t happen',reduce:'Lower the probability or impact',transfer:'Pass it to a party better placed to manage it (contract, insurance)',accept:'Take it on, with contingency and a fallback',exploit:'Make sure the opportunity happens',enhance:'Raise its probability or benefit',share:'Partner with a party who can help realise it'}[p.strat]||'';
  return `<div class="pfl"><span>Response strategy</span><div class="sg rk-strat" role="group" aria-label="Response strategy">${S.map(([k,l])=>`<button type="button" data-rkstrat="${k}" class="${p.strat===k?'on':''}">${l}</button>`).join('')}</div>${hint?`<small class="muted">${hint}</small>`:''}</div>
    <div class="rk-g3">${rkIn_('d.resp.owner',p.owner,{l:'Response owner',list:'rkOwners'})}${rkIn_('d.resp.cont',p.cont,{l:`Contingency held (${rkCfg().cur||'$'})`,t:'number',step:'any'})}${rkIn_('d.resp.contd',p.contd,{l:'Schedule contingency (days)',t:'number',step:'any'})}</div>
    ${rkIn_('d.resp.plan',p.plan,{l:'Response plan',ta:1,rows:3})}
    <div class="rk-g2">${rkIn_('d.resp.trigger',p.trigger,{l:'Trigger / early warning',ta:1,rows:2})}${rkIn_('d.resp.fallback',p.fallback,{l:'Fallback plan',ta:1,rows:2,hint:'What you do if it happens anyway'})}</div>
    <h4 class="rk-h4">Actions</h4>
    <div class="ptw"><table class="ptab rk-at"><thead><tr><th style="min-width:240px">Action</th><th>Owner</th><th>Due</th><th>Status</th><th>Cost</th><th></th></tr></thead><tbody>${r.d.actions.map((a,i)=>`<tr class="${rkOverdue(a)?'rk-odr':''}"><td><input data-ai="${i}.t" value="${esc(a.t||'')}" placeholder="What will be done" aria-label="Action"></td><td><input data-ai="${i}.owner" value="${esc(a.owner||'')}" list="rkOwners" aria-label="Owner"></td><td><input type="date" data-ai="${i}.due" value="${a.due?xD(a.due):''}" aria-label="Due"></td><td><select data-ai="${i}.status" aria-label="Status">${Object.entries(RACT).map(([v,l])=>`<option value="${v}"${a.status===v?' selected':''}>${l}</option>`).join('')}</select></td><td><input type="number" step="any" data-ai="${i}.cost" value="${esc(a.cost??'')}" aria-label="Cost" class="rk-num"></td><td><button type="button" class="fx" data-rkadel="${i}" aria-label="Remove action">×</button></td></tr>`).join('')||'<tr><td colspan="6" class="muted">No actions yet.</td></tr>'}</tbody></table></div>
    <datalist id="rkOwners">${[...new Set(RK.risks.flatMap(x=>[x.d.owner,...rkActs(x).map(a=>a.owner)]).filter(Boolean))].sort().map(o=>`<option value="${esc(o)}">`).join('')}</datalist>
    <div class="adm-acts"><button type="button" class="btn sm" data-rke="addact">Add action</button></div>`; }
function rkEdLinks(r){ const E=RK.ed, opts=rkParentOptions(r), par=rkById(r.parentId), kids=E.isNew?[]:rkKids(r), ed=rkCanEdit(), ifc=r.d.ifc, G=PER.programmes||[];
  const pOpts=[['','No parent']].concat(opts.sort((a,b)=>rkRank(a.level)-rkRank(b.level)||String(a.ref).localeCompare(b.ref)).map(p=>[p.id,`${RLV_L[p.level]} · ${p.ref} ${p.title}`]));
  const projBox=p=>`<label class="rk-pjb" title="${esc(p.code||'')}"><input type="checkbox" data-rkpj="${esc(p.id)}" ${ifc.pids.includes(p.id)?'checked':''}> <span>${esc(p.name)}</span></label>`;
  const gs=new Set(ifc.pids.map(id=>(rkProj(id)||{}).programmeId||'-')), need=gs.size>1?'portfolio':'programme';
  return `<h4 class="rk-h4">Parent risk</h4>
    ${r.level==='portfolio'?'<p class="muted">Portfolio risks are the top of the hierarchy, so they have no parent.</p>':`${rkSel_('parentId',r.parentId||'',pOpts,{l:'Rolls up to',hint:`A parent sits in a higher register: ${r.level==='project'?'this programme or the portfolio':'the portfolio'}.`})}
    ${par?`<button type="button" class="rk-card" data-rkgo="${esc(par.id)}"><span class="rk-lv l${rkRank(par.level)}">${RLV_L[par.level]}</span><span class="rk-ref">${esc(par.ref)}</span><span class="rk-tt">${esc(par.title)}</span>${rkChip(rkCurScore(par),{short:1})}</button>`:''}
    ${!E.isNew&&!r.parentId&&ed?`<div class="adm-acts">${r.level==='project'&&rkProgOf(r)?'<button type="button" class="btn sm" data-rke="esc:programme">Escalate to programme</button>':''}<button type="button" class="btn sm" data-rke="esc:portfolio">Escalate to portfolio</button><span class="muted">Creates a parent risk in that register and links this one to it.</span></div>`:''}`}
    <h4 class="rk-h4">Child risks</h4>
    ${r.level==='project'?'<p class="muted">Project risks are the lowest level, so they have no children.</p>':E.isNew?'<p class="muted">Add the risk first, then add child risks in the registers below.</p>':`${kids.length?kids.map(k=>`<button type="button" class="rk-card" data-rkgo="${esc(k.id)}"><span class="rk-lv l${rkRank(k.level)}">${RLV_L[k.level]}</span><span class="rk-ref">${esc(k.ref)}</span><span class="rk-tt">${esc(k.title)}<span class="muted"> · ${esc(rkScopeName(rkScopeOf(k)))}</span></span>${rkChip(rkCurScore(k),{short:1})}<span class="num">${rkMoney(rkEV(k,false,'cost'))}</span></button>`).join(''):'<p class="muted">No child risks yet.</p>'}${ed?'<div class="adm-acts"><button type="button" class="btn sm" data-rke="child">Add child risk</button></div>':''}`}
    <h4 class="rk-h4">Interface</h4>
    <label class="tg"><input type="checkbox" data-e="d.ifc.on" data-t="bool" ${ifc.on?'checked':''}> This risk sits at an interface between projects</label>
    ${ifc.on?`<div class="rk-pjl">${G.map(g=>{ const ps=PER.projects.filter(p=>p.programmeId===g.id); return ps.length?`<div class="rk-pjg"><b>${esc(g.name)}</b>${ps.map(projBox).join('')}</div>`:''; }).join('')}${(()=>{ const ps=PER.projects.filter(p=>!p.programmeId||!G.some(g=>g.id===p.programmeId)); return ps.length?`<div class="rk-pjg"><b>Not in a programme</b>${ps.map(projBox).join('')}</div>`:''; })()}</div>
      ${rkIn_('d.ifc.code',ifc.code,{l:'Interface ID',ph:'e.g. IF-07',hint:'Matches the Interface ID activity code in the schedules, if you use one'})}
      ${ifc.pids.length<2&&r.level!=='project'?'<p class="pwarn">Tick at least two projects.</p>':''}${ifc.pids.length>=2&&rkRank(r.level)>rkRank(need)?`<p class="pwarn">These projects ${need==='portfolio'?'are in different programmes':'share a programme'}: consider owning this risk in the ${need} register so both sides see it.</p>`:''}`:''}`; }
function rkEdHist(r){ const h=(r.d.hist||[]).slice().reverse();
  return `<p class="muted">${RK.ed.isNew?'History starts when the risk is added.':`Added ${r.createdAt?fmtD(r.createdAt):r.d.raised?fmtD(r.d.raised):''} · last saved ${r.updatedAt?fmtD(r.updatedAt):'—'}. A line is recorded whenever the score, exposure or status changes, or when it’s marked reviewed.`}</p>
    <div class="ptw"><table class="ptab"><thead><tr><th>Date</th><th>By</th><th>Status</th><th>Current</th><th>Target</th><th class="num">Cost exposure</th><th class="num">Schedule exposure</th></tr></thead><tbody>${h.map(x=>`<tr><td class="num">${fmtD(x.at)}</td><td>${esc(x.by||'')}</td><td>${esc(RST[x.st]||x.st||'')}</td><td>${rkChip(x.cur,{short:1})}</td><td>${rkChip(x.tgt,{short:1})}</td><td class="num">${rkMoney(x.ev)}</td><td class="num">${rkDays(x.evt)}</td></tr>`).join('')||'<tr><td colspan="7" class="muted">Nothing recorded yet.</td></tr>'}</tbody></table></div>`; }
/* editor events */
function rkEdVal(t){ const ty=t.dataset.t; if(ty==='bool') return t.checked; if(ty==='date') return t.value?Date.parse(t.value+'T00:00:00Z'):null; if(ty==='number') return t.value===''?'':+t.value; return t.value; }
function rkEdInput(e){ const t=e.target; if(!RK.ed) return; if(t.dataset.e&&t.type!=='checkbox'&&t.tagName!=='SELECT'){ if(t.dataset.e==='title'){ RK.ed.r.title=t.value; const h=document.getElementById('rkShT'); if(h) h.textContent=t.value||'New risk'; return; } rkSet(RK.ed.r,t.dataset.e,rkEdVal(t)); if(/^d\.qt\./.test(t.dataset.e)) rkEdRendered(); }
  else if(t.dataset.ai&&t.tagName!=='SELECT'){ const [i,k]=t.dataset.ai.split('.'), a=RK.ed.r.d.actions[+i]; if(a) a[k]=k==='due'?(t.value?Date.parse(t.value+'T00:00:00Z'):null):k==='cost'?(t.value===''?'':+t.value):t.value; } }
function rkEdChange(e){ const t=e.target, E=RK.ed; if(!E) return; const r=E.r;
  if(t.dataset.e==='_reg'){ const [lv,id]=t.value.split(':'); r.level=lv; r.programmeId=lv==='programme'?id:null; r.projectId=lv==='project'?id:null; if(r.parentId&&!rkParentOptions(r).some(p=>p.id===r.parentId)){ r.parentId=null; perToast('The parent link was removed because it no longer sits above this register.'); } rkEdRender(); return; }
  if(t.dataset.e){ if(t.dataset.e==='parentId'){ r.parentId=t.value||null; rkEdRender(); return; } rkSet(r,t.dataset.e,rkEdVal(t)); if(t.dataset.e==='d.type'){ r.d.resp.strat=''; } if(t.tagName==='SELECT'||t.type==='checkbox') rkEdRender(); else if(/^d\.qt\./.test(t.dataset.e)) rkEdRendered(); return; }
  if(t.dataset.ai){ const [i,k]=t.dataset.ai.split('.'), a=r.d.actions[+i]; if(!a) return; if(k==='status'){ a.status=t.value; if(t.value==='done'&&!a.doneAt) a.doneAt=Date.now(); rkEdRender(); } else rkEdInput(e); return; }
  if(t.dataset.rkpj){ const ids=new Set(r.d.ifc.pids); t.checked?ids.add(t.dataset.rkpj):ids.delete(t.dataset.rkpj); r.d.ifc.pids=[...ids]; rkEdRender(); } }
async function rkEdClick(e){ const t=e.target, E=RK.ed; if(!E) return; const r=E.r;
  const tb=t.closest('[data-rket]'); if(tb){ RK.edTab=tb.dataset.rket; rkEdRender(); return; }
  const st=t.closest('[data-rkstrat]'); if(st){ r.d.resp.strat=r.d.resp.strat===st.dataset.rkstrat?'':st.dataset.rkstrat; rkEdRender(); return; }
  const ad=t.closest('[data-rkadel]'); if(ad){ r.d.actions.splice(+ad.dataset.rkadel,1); rkEdRender(); return; }
  const go=t.closest('[data-rkgo]'); if(go){ const x=rkById(go.dataset.rkgo); if(x){ if(rkDirty()&&!confirmIn(go,'Unsaved changes — click again to leave')) return; rkOpen(x,'links'); } return; }
  const b=t.closest('[data-rke]'); if(!b) return; const k=b.dataset.rke;
  if(k==='close'){ if(b.classList.contains('fx')) rkEdAsk(); else if(!rkDirty()||confirmIn(b,'Discard changes?')) rkEdClose(); return; }
  if(k==='addact'){ r.d.actions.push({id:'a'+Math.random().toString(36).slice(2,8),t:'',owner:r.d.resp.owner||r.d.owner||'',due:rkToday()+14*DAY,status:'todo',cost:''}); rkEdRender(); const ins=document.querySelectorAll('#rkSheet [data-ai$=".t"]'); if(ins.length) ins[ins.length-1].focus(); return; }
  if(k==='copyq'){ r.d.q.cur=rkClone(r.d.q.pre); rkEdRender(); return; }
  if(k==='suggest'){ const c=rkCfg(), x=rkQt(r), cd=c.dims.find(d=>d.kind==='cost'), td=c.dims.find(d=>d.kind==='time'), cu=r.d.q.cur; cu.p=rkProbScore(x.p)||cu.p; cu.i=cu.i||{};
    const ml=t2=>{ const v=t2&&t2.ml!==''&&t2.ml!=null?+t2.ml:null; return v; }; if(cd){ const v=ml(r.d.qt.cost); if(v!=null) cu.i[cd.id]=rkImpactFromValue(cd,v); } if(td){ const v=ml(r.d.qt.time); if(v!=null) cu.i[td.id]=rkImpactFromValue(td,v); }
    rkEdRender(); perToast('Current probability and impacts set from the most likely values.'); return; }
  if(k==='save'||k==='reviewed'){ if(!r.title.trim()){ RK.edTab='det'; rkEdRender(); const ti=document.querySelector('#rkSheet [data-e="title"]'); if(ti){ ti.focus(); ti.setCustomValidity('Give the risk a title.'); ti.reportValidity(); setTimeout(()=>ti.setCustomValidity(''),2000); } return; }
    if(r.parentId&&!rkParentOptions(r).some(p=>p.id===r.parentId)) r.parentId=null;
    r.d.actions=r.d.actions.filter(a=>String(a.t||'').trim());
    if(k==='reviewed'){ r.d.review=rkToday()+rkCfg().review*DAY; r.d.lastReview=Date.now(); r.d._reviewed=true; }
    b.disabled=true;
    try{ if(E.isNew){ const id=await rkCreate(r); perToast(`Added ${r.ref||'the risk'}.`); } else { await rkUpdate(r); perToast(k==='reviewed'?`Review recorded. Next review ${fmtD(r.d.review)}.`:'Risk saved.'); } rkEdClose(); }
    catch(er){ b.disabled=false; perToast(perErr(er),'err'); } return; }
  if(k==='del'){ if(!confirmIn(b,rkKids(r).length?`Delete? ${rkKids(r).length} child risk${rkKids(r).length===1?'':'s'} will be unlinked`:'Click again to delete')) return; try{ await rkDelete(r); perToast(`Deleted ${r.ref}.`); rkEdClose(); }catch(er){ perToast(perErr(er),'err'); } return; }
  if(k==='child'){ if(rkDirty()&&!confirmIn(b,'Save first? Click again to discard')) return; const p=rkById(r.id); rkEdClose(); setTimeout(()=>rkNewChild(p),220); return; }
  if(k.startsWith('esc:')){ if(rkDirty()) { try{ await rkUpdate(r); }catch(er){ perToast(perErr(er),'err'); return; } } const lv=k.slice(4), x=rkById(r.id)||r; rkEdClose(); rkEscalate(x,lv); return; }
}

/* ================= Register configuration (admin) ================= */
function rkCfgOpen(){ if(!rkAdmin()) return; if(PER.mode==='supa'){ admGo('co-risk'); return; }
  RK.ce=rkClone(rkCfg()); const d=coModal('rkCfgM','wide rk-cfgm'); d.querySelector('.mcard').innerHTML=`<div class="mh"><h2>Risk register settings</h2><button class="fx" data-cox aria-label="Close">×</button></div>${rkCfgHtml('modal')}`; d.querySelector('.fx').focus(); }
function rkCfgRefresh(){ const el=document.getElementById('rkCfg'); if(!el) return; const y=el.closest('.modal')?el.closest('.modal').scrollTop:window.scrollY; el.outerHTML=rkCfgHtml(el.dataset.ctx); const m=document.getElementById('rkCfg').closest('.modal'); if(m) m.scrollTop=y; else window.scrollTo(0,y); }
function rkColChooser(path,cols){ const defs=rkColDefs(), shown=(cols||[]).filter(k=>k in defs), avail=Object.keys(defs).filter(k=>!shown.includes(k));
  return `<div class="rk-cc"><div><div class="fh">Shown, in order</div>${shown.map((k,i)=>`<div class="rk-cci"><span>${esc(defs[k])}</span><span class="sp"></span>${RCOL_REQ.includes(k)?'<span class="muted">always</span>':`<button type="button" class="fx" data-rkc="up" data-p="${path}" data-k="${esc(k)}" ${i===0?'disabled':''} aria-label="Move up">↑</button><button type="button" class="fx" data-rkc="dn" data-p="${path}" data-k="${esc(k)}" ${i===shown.length-1?'disabled':''} aria-label="Move down">↓</button><button type="button" class="fx" data-rkc="rm" data-p="${path}" data-k="${esc(k)}" aria-label="Hide ${esc(defs[k])}">×</button>`}</div>`).join('')}</div>
    <div><div class="fh">Available</div><div class="rk-cca">${avail.map(k=>`<button type="button" class="rk-ccb" data-rkc="add" data-p="${path}" data-k="${esc(k)}">+ ${esc(defs[k])}</button>`).join('')||'<span class="muted">Everything is shown.</span>'}</div></div></div>`; }
function rkCfgHtml(ctx){ const c=RK.ce||(RK.ce=rkClone(rkCfg())), G=PER.programmes||[];
  const al=[['aligned','Aligned','Every register — portfolio, programme and project — uses the same format. Easiest to compare and roll up.'],['tiered','Tiered','Portfolio, programme and project registers each have their own format, so each level shows what matters at that level.'],['cascade','Programme-led','The portfolio has its own format. Each programme can tailor its register, and its projects follow their programme’s format.']];
  let tabs=c.align==='aligned'?[['all','All registers']]:c.align==='tiered'?[['portfolio','Portfolio'],['programme','Programme'],['project','Project']]:[['portfolio','Portfolio'],['programme','Programme default'],['project','Project default']].concat(RK.ceProg?[]:[]);
  if(!tabs.some(t=>t[0]===RK.ceLv)&&!(c.align==='cascade'&&RK.ceLv==='prog')) RK.ceLv=tabs[0][0];
  const path=RK.ceLv==='prog'?'progCols.'+RK.ceProg:'cols.'+RK.ceLv, cur=RK.ceLv==='prog'?(c.progCols[RK.ceProg]||c.cols.programme).slice():c.cols[RK.ceLv];
  const progList=c.align==='cascade'?`<div class="rk-progf"><div class="fh">Programme formats</div>${G.map(g=>`<div class="rk-cci${RK.ceLv==='prog'&&RK.ceProg===g.id?' on':''}"><span>${esc(g.name)}</span><span class="sp"></span><span class="muted">${c.progCols[g.id]?'Tailored':'Uses the default'}</span><button type="button" class="link" data-rkc="prog" data-k="${esc(g.id)}">${c.progCols[g.id]?'Edit':'Tailor'}</button>${c.progCols[g.id]?`<button type="button" class="link" data-rkc="progreset" data-k="${esc(g.id)}">Reset</button>`:''}</div>`).join('')||'<p class="muted">No programmes yet.</p>'}<p class="muted">A tailored programme’s projects use its format.</p></div>`:'';
  const prevMax=[0].concat(c.prob.map(p=>p.max));
  const fields=`<div class="rk-fl">${c.fields.map((f,i)=>`<div class="rk-fli"><input data-rkc-v="fields.${i}.l" value="${esc(f.l)}" aria-label="Field name"><select data-rkc-v="fields.${i}.type" aria-label="Field type">${[['text','Text'],['number','Number'],['date','Date'],['choice','Choice']].map(([v,l])=>`<option value="${v}"${f.type===v?' selected':''}>${l}</option>`).join('')}</select>${f.type==='choice'?`<input data-rkc-v="fields.${i}.opts" data-list="1" value="${esc((f.opts||[]).join(', '))}" placeholder="Options, separated by commas" aria-label="Options">`:'<span></span>'}<button type="button" class="fx" data-rkc="frm" data-k="${i}" aria-label="Remove field">×</button></div>`).join('')}<button type="button" class="btn sm" data-rkc="fadd">Add a field</button></div>`;
  const dims=c.dims.map((d,i)=>`<div class="rk-dim"><div class="rk-dimh"><input data-rkc-v="dims.${i}.l" value="${esc(d.l)}" aria-label="Impact name"><span class="muted">${d.kind==='cost'?`cost thresholds (${esc(c.cur)})`:d.kind==='time'?'schedule thresholds (days)':'descriptions'}</span>${d.kind==='text'?`<button type="button" class="fx" data-rkc="drm" data-k="${i}" aria-label="Remove impact">×</button>`:''}</div>
      <div class="rk-dimv">${d.kind==='text'?(d.d||[]).map((x,j)=>`<label><span>${j+1}</span><input data-rkc-v="dims.${i}.d.${j}" value="${esc(x)}"></label>`).join(''):(d.b||[]).map((x,j)=>`<label><span>${j+1}→${j+2} above</span><input type="number" step="any" data-rkc-v="dims.${i}.b.${j}" data-n="1" value="${esc(x)}"></label>`).join('')}</div></div>`).join('');
  const save=`<div class="adm-acts rk-cfga"><button type="button" class="btn primary" data-rkc="save">Save settings</button>${ctx==='modal'?'<button type="button" class="btn" data-cox>Cancel</button>':''}<button type="button" class="link danger" data-rkc="reset">Reset to defaults</button></div>`;
  return `<div id="rkCfg" class="rk-cfg" data-ctx="${ctx}">
    <section><h3>How registers line up</h3><div class="rk-al">${al.map(([k,l,dsc])=>`<label class="rk-alo${c.align===k?' on':''}"><input type="radio" name="rkal" data-rkc-v="align" value="${k}" ${c.align===k?'checked':''}><b>${l}</b><span class="muted">${dsc}</span></label>`).join('')}</div>
      <p class="muted">Whatever the format, every register shares the scoring matrix and categories below, so risks can be escalated, rolled up and compared.</p></section>
    <section><h3>Columns</h3><div class="ptabs">${tabs.map(([k,l])=>`<button type="button" aria-selected="${RK.ceLv===k}" data-rkc="lv" data-k="${k}">${l}</button>`).join('')}${RK.ceLv==='prog'?`<button type="button" aria-selected="true">${esc((rkProg(RK.ceProg)||{}).name||'Programme')}</button>`:''}</div>
      <div class="rk-ccw">${rkColChooser(path,cur)}${progList}</div></section>
    <section><h3>Your own fields</h3><p class="muted">Extra fields appear on the risk form and can be added as columns.</p>${fields}</section>
    <section><h3>Scoring matrix</h3><p class="muted">Score = probability × the highest impact across the dimensions.</p>
      <div class="rk-g2"><div><div class="fh">Probability (upper bound %)</div>${c.prob.map((p,i)=>`<div class="rk-pb"><b>${i+1}</b><input data-rkc-v="prob.${i}.l" value="${esc(p.l)}" aria-label="Probability ${i+1} name"><span class="muted">${prevMax[i]}% to</span><input type="number" min="1" max="100" data-n="1" data-rkc-v="prob.${i}.max" value="${p.max}" ${i===4?'disabled':''} aria-label="Upper bound"><span class="muted">%</span></div>`).join('')}</div>
        <div><div class="fh">Rating bands (highest score)</div>${c.bands.map((b,i)=>`<div class="rk-pb"><input type="color" data-rkc-v="bands.${i}.c" value="${esc(b.c)}" aria-label="Colour"><input data-rkc-v="bands.${i}.l" value="${esc(b.l)}" aria-label="Band name"><span class="muted">up to</span><input type="number" min="1" max="25" data-n="1" data-rkc-v="bands.${i}.max" value="${b.max}" ${i===3?'disabled':''} aria-label="Highest score"></div>`).join('')}
          <div class="fh">Impact labels</div><div class="rk-il">${c.ilab.map((l,i)=>`<input data-rkc-v="ilab.${i}" value="${esc(l)}" aria-label="Impact ${i+1} label">`).join('')}</div></div></div>
      <div class="fh">Impact dimensions</div>${dims}<button type="button" class="btn sm" data-rkc="dadd">Add an impact dimension</button>
      <div class="fh">Preview</div><div class="rk-prev">${(()=>{ const o=RK.cfg; RK.cfg=c; const h=rkHeat([],'cur',{}); RK.cfg=o; return h.replace(/<button/g,'<div').replace(/<\/button>/g,'</div>'); })()}</div></section>
    <section><h3>Categories, review and escalation</h3><div class="rk-g2"><label class="pfl"><span>Categories, one per line</span><textarea rows="8" data-rkc-v="cats" data-lines="1">${esc(c.cats.join('\n'))}</textarea></label>
      <div><div class="rk-g2">${`<label class="pfl"><span>Review every (days)</span><input type="number" min="1" data-n="1" data-rkc-v="review" value="${c.review}"></label><label class="pfl"><span>Currency symbol</span><input maxlength="4" data-rkc-v="cur" value="${esc(c.cur)}"></label>`}</div>
        <div class="fh">Suggest escalation when a risk reaches</div>${['programme','portfolio'].map(lv=>`<div class="rk-pb"><b>${RLV_L[lv]}</b><span class="muted">score ≥</span><input type="number" min="1" max="25" data-n="1" data-rkc-v="esc.${lv}.score" value="${c.esc[lv].score}"><span class="muted">or cost exposure ≥</span><input type="number" step="any" data-n="1" data-rkc-v="esc.${lv}.cost" value="${c.esc[lv].cost}"></div>`).join('')}</div></div></section>
    ${save}</div>`; }
function rkCfgClick(e){ const b=e.target.closest('[data-rkc]'); if(!b||!document.getElementById('rkCfg')||!b.closest('#rkCfg')) return; const c=RK.ce, k=b.dataset.rkc, key=b.dataset.k;
  const arr=p=>{ const ks=p.split('.'); let o=c; ks.slice(0,-1).forEach(x=>o=o[x]=o[x]||{}); if(!Array.isArray(o[ks[ks.length-1]])) o[ks[ks.length-1]]=(p.startsWith('progCols.')?c.cols.programme:[]).slice(); return o[ks[ks.length-1]]; };
  if(k==='add'){ arr(b.dataset.p).push(key); } else if(k==='rm'){ const a=arr(b.dataset.p); a.splice(a.indexOf(key),1); }
  else if(k==='up'||k==='dn'){ const a=arr(b.dataset.p), i=a.indexOf(key), j=k==='up'?i-1:i+1; if(j>=0&&j<a.length){ [a[i],a[j]]=[a[j],a[i]]; } }
  else if(k==='lv'){ RK.ceLv=key; } else if(k==='prog'){ if(!c.progCols[key]) c.progCols[key]=c.cols.programme.slice(); RK.ceLv='prog'; RK.ceProg=key; } else if(k==='progreset'){ delete c.progCols[key]; if(RK.ceProg===key) RK.ceLv='programme'; }
  else if(k==='fadd'){ c.fields.push({id:'f'+Date.now().toString(36),l:'New field',type:'text'}); } else if(k==='frm'){ const f=c.fields.splice(+key,1)[0]; if(f){ const id='f:'+f.id; ['all','portfolio','programme','project'].forEach(l=>c.cols[l]=c.cols[l].filter(x=>x!==id)); Object.keys(c.progCols).forEach(g=>c.progCols[g]=c.progCols[g].filter(x=>x!==id)); } }
  else if(k==='dadd'){ c.dims.push({id:'d'+Date.now().toString(36),l:'New impact',kind:'text',d:['','','','','']}); } else if(k==='drm'){ c.dims.splice(+key,1); }
  else if(k==='reset'){ if(!confirmIn(b,'Click again to reset')) return; RK.ce=rkDefaultCfg(); RK.ceLv='all'; }
  else if(k==='save'){ b.disabled=true; const cfg=rkClone(RK.ce); for(let i=1;i<cfg.prob.length;i++) if(cfg.prob[i].max<=cfg.prob[i-1].max) cfg.prob[i].max=Math.min(100,cfg.prob[i-1].max+1); cfg.prob[4].max=100;
      for(let i=1;i<cfg.bands.length;i++) if(cfg.bands[i].max<=cfg.bands[i-1].max) cfg.bands[i].max=Math.min(25,cfg.bands[i-1].max+1); cfg.bands[3].max=25; cfg.cats=cfg.cats.map(s=>String(s).trim()).filter(Boolean);
      rkSaveCfg(cfg).then(()=>{ perToast('Risk register settings saved.'); const m=document.getElementById('rkCfgM'); if(m) m.remove(); else { RK.ce=rkClone(rkCfg()); rkCfgRefresh(); } rkRender(); }).catch(er=>{ b.disabled=false; perToast(perErr(er),'err'); }); return; }
  rkCfgRefresh(); }
function rkCfgChange(e){ const t=e.target; if(!t.dataset||t.dataset.rkcV==null||!t.closest('#rkCfg')) return; const c=RK.ce; let v=t.value;
  if(t.dataset.n) v=+v; if(t.dataset.lines) v=v.split('\n'); if(t.dataset.list) v=v.split(',').map(s=>s.trim()).filter(Boolean);
  rkSet(c,t.dataset.rkcV,v); if(t.dataset.rkcV==='align'||/\.type$/.test(t.dataset.rkcV)||/^(prob|bands)\./.test(t.dataset.rkcV)||/^ilab/.test(t.dataset.rkcV)) rkCfgRefresh(); }

