async function rkSample(){ if(!rkCanEdit()) return; if(RK.risks.some(r=>r.d&&r.d.sample)){ perToast('The sample risks are already loaded.'); return; }
  await perRun('Loading sample risks…',async()=>{
    const gid={}, pid={};
    for(const key of SP_ORDER){ const D=SP_DEFS[key]; let g=PER.programmes.find(x=>x.code===D.code);
      gid[key]=g?g.id:await PER.store.createProgramme({name:D.name,code:D.code,client:D.client,description:D.desc,colour:D.colour});
      for(const pp of Object.values(D.pps)){ const p=PER.projects.find(x=>x.code===pp.code)||PER.projects.find(x=>x.programmeId===gid[key]&&x.name===pp.name); pid[pp.code]=p?p.id:await PER.store.createProject(pp.name,{programmeId:gid[key],code:pp.code,status:'active',manager:pp.manager,description:pp.desc}); } }
    const c=rkCfg(), dims=c.dims.map(d=>d.id), T=rkToday(), made={}, refs={};
    const mk=a=>({p:a[0],i:Object.fromEntries(dims.slice(0,4).map((d,i)=>[d,a[i+1]||0]).filter(x=>x[1]))});
    const order=RK_SAMPLE.slice().sort((a,b)=>rkRank(a.lv)-rkRank(b.lv));
    for(const s of order){ const sc=s.lv==='portfolio'?{lv:'portfolio'}:s.lv==='programme'?{lv:'programme',id:gid[s.g]}:{lv:'project',id:pid[s.p]};
      const r=rkBlank(sc); r.title=s.t; r.status=s.status||'open'; r.parentId=s.parent?made[s.parent]||null:null;
      const code=rkScopeCode(sc), n=(refs[code]=(refs[code]||0)+1); r.ref=`${code}-R${String(n).padStart(3,'0')}`;
      Object.assign(r.d,{sample:true,type:s.type||'threat',cat:s.cat,owner:s.own,cause:s.cause||'',event:s.ev||'',effect:s.eff||'',raised:T-(60+Math.round(n*7))*DAY,review:T+((n*11)%40-8)*DAY,prox:T+(30+n*9)*DAY});
      r.d.q={pre:mk(s.q[0]),cur:mk(s.q[1]),tgt:mk(s.q[2])};
      if(s.qt){ const q=s.qt; r.d.qt=Object.assign(r.d.qt,{p:q[0],cost:{min:q[1],ml:q[2],max:q[3]},time:{min:q[4],ml:q[5],max:q[6]},dist:'tri',post:{p:Math.max(5,Math.round(q[0]*.55)),cost:{min:Math.round(q[1]*.7),ml:Math.round(q[2]*.6),max:Math.round(q[3]*.6)},time:{min:Math.round(q[4]*.6),ml:Math.round(q[5]*.6),max:Math.round(q[6]*.6)}}}); }
      if(s.kids) r.d.qt.fromKids=true;
      r.d.resp=Object.assign(r.d.resp,{strat:s.strat||'',owner:s.own,plan:s.plan||'',fallback:s.fallback||''});
      r.d.actions=(s.acts||[]).map((a,i)=>({id:'a'+i,t:a[0],owner:a[1],due:T+a[2]*DAY,status:a[3],cost:'',doneAt:a[3]==='done'?T+a[2]*DAY:null}));
      if(s.ifc){ r.d.ifc={on:true,pids:s.ifc.map(cd=>pid[cd]).filter(Boolean),code:s.ifcId||''}; }
      if(s.hist){ const cs=rkScore(r.d.q.cur); r.d.hist=[{at:T-35*DAY,by:'Sample',cur:cs-(s.hist>0?3:-3),tgt:rkScore(r.d.q.tgt),ev:0,evt:0,st:'open'}]; }
      made[s.k]=await rkCreate(r); }
    perToast(`Loaded ${RK_SAMPLE.length} sample risks across the portfolio, its four programmes and seven projects.`);
  });
}
